var n=`0709-thieboudienne-mauritanian-style`;var t=`world-0709`;var a=`MR`;var o=`western-africa`;var r=4;var s=85;var l={en:`Thieboudienne Mauritanian Style`,ua:`Тьєбуд'єн по-мавританськи`};var g={en:`Thieboudienne Mauritanian Style is a Mauritania classic prepared with tilapia, parsley, garlic, lemon juice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Тьєбуд'єн по-мавританськи, страва кухні країни Мавританія зі складниками: тилапія, петрушка, часник, лимонний сік. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`tilapia`,680,`g`],[`parsley`,30,`g`],[`garlic`,4,`clove`],[`lemon-juice`,25,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 13 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 13 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:13,i:[[`yellow-onion`,190,`g`],[`tomato-paste`,55,`g`],[`sunflower-oil`,50,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`water`,1050,`ml`],[`carrot`,220,`g`],[`eggplant`,210,`g`],[`white-cabbage`,200,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 26 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 26 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:26,i:[[`broken-rice`,370,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`scotch-bonnet-pepper`,1,`pcs`]]}];var d={slug:n,id:t,country:`MR`,region:o,servings:4,minutes:85,title:l,text:g,steps:u};export{a as country,d as default,t as id,s as minutes,o as region,r as servings,n as slug,u as steps,g as text,l as title};